[2383] = { en = "Simple Parchment", tier = 1,
  t = "Eenvoudig perkament",
  d = "Ah, terwijl je weg was, kwam er een perkament voor je, $N.$B$BLees het als je tijd hebt. Als ik me niet vergis, komt het van de krijgertrainer Frang. Hij wil met je praten als je klaar bent. Je vindt hem buiten de Den. Hij schuilt daar in de schaduw.",
  o = "Lees de Simple Parchment en praat met Frang in de Valley of Trials.",
  p = "Wat heb je daar? Een perkament? Je bent toch geen geleerde, hoop ik...",
  c = "Ah, dat is mijn perkament. Ik hoorde dat je naar de Valley zou komen, $N. Ik ben blij dat je het gehaald hebt. Laten we hopen dat je de beproevingen overleeft die voor je liggen. Zoals ik zei: kom naar mij als je meer kracht krijgt. Ik zal doen wat ik kan om je te trainen in de weg van de $C.$b$bSucces, $N. Kom terug naar mij als je je klaar voelt.",
