[3065] = { en = "Simple Tablet", tier = 1,
  t = "Eenvoudig tablet",
  d = "Ah, terwijl je weg was, kwam er een perkament voor je, $N.$B$BLees het als je tijd hebt. Als ik me niet vergis, komt het van de krijgertrainer Frang. Hij wil met je praten als je klaar bent. Je vindt hem buiten de Den. Hij schuilt daar in de schaduw.",
  o = "Lees de Simple Tablet en praat met Frang in de Valley of Trials.",
  p = "Weer een $R om de rijen te versterken. Goed genoeg voor mij.$B$BJe zult waarschijnlijk moeite hebben om een goed wapen zoals een bijl op te tillen. Maar een speer is net zo goed als elk ander wapen.$B$BWelkom in de Valley of Trials.",
  c = "Je zult zien dat deze plek goed bij je past, terwijl je verder traint in de weg van de $C. Als je vragen hebt, vraag het dan gerust aan iemand hier. En als je je klaar voelt, kom dan terug naar mij voor training. Ik beheers net zoveel als elke andere $C hier in de Valley. Ik kan die kennis aan je doorgeven... voor een prijs.",
