[3091] = { en = "Simple Note", tier = 1,
  t = "Eenvoudig briefje",
  d = "Een moment geleden zocht een boodschapper naar je, $N. Ik denk dat de krijgertrainer Harutt haar stuurde. Als dit briefje van Harutt is, zou ik niet lang wachten met lezen.$b",
  o = "Lees de Simple Note en praat met Harutt Thunderhorn in Camp Narache.",
  p = "Ah, eindelijk ben je er, $c. Ik loog niet in mijn briefje, $N. Wij zijn ook een speciaal soort, net als de druïden of sjamanen van onze stam. Jij bent net zo belangrijk. Ze roepen ons om onze grenzen te verdedigen, om op de centauren te jagen en om oorlog te voeren.",
  c = "Ieder van ons heeft een rol in onze stam. Ieder van ons moet ook door dezelfde rituelen gaan. Laat je trots je nooit iets anders vertellen.$B$BIk blijf hier om nieuwe krijgers te trainen. Zij zoeken de glorie van de strijd en volgen de wegen van onze oudste voorouders. Kom terug naar mij als je je klaar voelt. Dan zal ik doen wat ik kan om je verder te trainen. Ga met de zegen van de stam, $N.",
  g = { {"briefje", "note (brief)"}, {"boodschapper", "messenger"}, {"loog", "lied (liegen)"}, {"soort", "kind, breed"}, {"druïden", "druids (druïde)"}, {"sjamanen", "shamans (sjamaan)"}, {"stam", "tribe"}, {"grenzen", "borders (grens)"}, {"centauren", "centaurs (centaur)"}, {"rituelen", "rites, rituals (ritueel)"}, {"trots", "pride"}, {"voorouders", "ancestors (voorouder)"}, {"zegen", "blessing"} },
},

[3095] = { en = "Simple Scroll", tier = 1,
  t = "Eenvoudige perkamentrol",
  d = "Ah, terwijl jij bezig was met de hersenloze Scourge, kwam deze rol voor je aan. Ik denk dat het iets belangrijks is, want hij lijkt het zegel van de krijgertrainer Dannal te dragen. Ik zou de tijd nemen om hem te lezen, voordat je weer vertrekt.",
  o = "Lees de Simple Scroll en praat met Dannal Stern in Deathknell.",
  p = "Ah, dus je bent er. Goed. Ik heb toevallig gehoord dat een paar anderen aan de \"dood\" konden ontsnappen. Ze waren op weg naar het dorp. Misschien heb je later ook nog iets aan die taaiheid.$B$BJe mag Sylvanas bedanken voor je vrijheid... vrijheid van geest en lichaam. De pest en de gevolgen ervan kwellen je nog steeds. Maar je bent nu vrij om te gaan en te komen zoals jij wilt.",
  c = "Ik ben hier om je te trainen als je meer ervaring krijgt... kom zo vaak als je wilt. Ik vraag een kleine prijs, maar je zult zien dat alles wat ik je kan leren de moeite waard is.$B$BGa nu en test je vaardigheid. Je zult nog veel meer dingen leren als je ervaring krijgt. Over sommige dingen kan ik hier niet met je praten. Weet alleen dat Sylvanas in de toekomst krijgers met jouw soort kracht nodig heeft. Jij wordt de ruggengraat van onze redding. Vergeet dat niet.",
  g = { {"perkamentrol", "scroll"}, {"hersenloze", "mindless (hersenloos)"}, {"zegel", "seal"}, {"toevallig", "by chance"}, {"ontsnappen", "to escape"}, {"taaiheid", "toughness, resilience"}, {"geest", "mind, spirit"}, {"pest", "plague"}, {"gevolgen", "effects, consequences (gevolg)"}, {"kwellen", "torment (kwellen)"}, {"de moeite waard", "worthwhile"}, {"vaardigheid", "skill"}, {"ruggengraat", "backbone"}, {"redding", "salvation, rescue"} },
},

[1498] = { en = "Path of Defense", tier = 1,
  t = "Het pad van de verdediging",
  d = "Als krijger hebben we een heel belangrijke taak... bescherming. Wij zijn het schild van de Horde, en we houden onze zwakkere broeders veilig. Als je bij ons wilt horen, moet je me laten zien wat je waard bent.$B$BGa naar Thunder Ridge in Durotar. Daar wonen de Lightning Hides en de Thunder Lizards. Jaag op de beesten! Laat me zien dat jij taaier bent dan zij! Trotseer hun aanvallen en breng me een stapel van hun verschroeide schubben als bewijs.$B$BDoe dit, en dan zal ik je lesgeven.",
  o = "Breng 5 Singed Scales naar Uzzek bij Far Watch Post in de Barrens.",
  p = "Heb je de schubben, $N? Als je de aanvallen van de Thunder Lizards niet kunt weerstaan, heb je niets aan mijn lessen.",
  c = "Ah. Ik zie dat je de Thunder Lizards hebt verslagen. Dat bewijst dat je taai bent. Nu zal ik je laten zien hoe een taaie huid en slimme bewegingen samen een muur van verdediging maken. Niemand komt door die muur heen.$B$BLeer je les goed, $N. En wees klaar voor nieuwe lessen.",
  g = { {"verdediging", "defence"}, {"bescherming", "protection"}, {"schild", "shield"}, {"broeders", "brethren, brothers (broeder)"}, {"wat je waard bent", "what you're worth, your mettle"}, {"taaier", "tougher (taai)"}, {"Trotseer", "brave, defy (trotseren)"}, {"stapel", "stack, pile"}, {"verschroeide", "singed (verschroeien)"}, {"schubben", "scales (schub)"}, {"bewijs", "proof"}, {"weerstaan", "to withstand"}, {"verslagen", "defeated (verslaan)"}, {"huid", "skin, hide"} },
},

[1502] = { en = "Thun'grim Firegaze", tier = 1,
  t = "Thun'grim Firegaze",
  d = "Het is heel belangrijk dat het wapen van een krijger van goede kwaliteit is. En als er een orc is die goede wapens kan maken, dan is dat Thun'grim Firegaze. Hij is een kluizenaar. Hij woont boven op de heuvels ten oosten van de Crossroads.$B$BAls je een wapen zoekt, krijger, dan moet je Thun'grim zoeken. Om hem te vinden, reis je eerst naar de Crossroads in het westen. Ga dan naar het oosten, de heuvels in. Zijn kamp ligt hoog op een heuveltop.",
  o = "Praat met Thun'grim Firegaze in de Barrens.",
  c = "Mijn ogen zijn al lang uitgedroogd van het staren in het vuur van de smidse, maar sommige dingen zie ik nog. Ik zie dat je iets wilt.$b$bEn als je de weg hierheen hebt gevonden, dan kan ik raden wat je wilt.",
  g = { {"kwaliteit", "quality"}, {"kluizenaar", "hermit"}, {"heuvels", "hills (heuvel)"}, {"ten oosten van", "east of"}, {"heuveltop", "hilltop"}, {"uitgedroogd", "dried out (uitdrogen)"}, {"staren", "staring"}, {"smidse", "forge, smithy"}, {"raden", "to guess"} },
},

[1503] = { en = "Forged Steel", tier = 1,
  t = "Gesmeed staal",
  d = "Ik zal je een wapen geven, $N, maar eerst moet je mij helpen. De Razormanes in het noordwesten kwamen een paar nachten geleden in mijn kamp. Ze wilden niet met me vechten, maar ze weten dat mijn ogen slecht zijn. Een paar van hen leidden me af met gesnuif, en de anderen stalen van me! De lafaards!$B$BZe namen een ijzeren kist mee, en daarin zaten een paar staven gesmeed staal. Als je ze terug kunt halen, geef ik je het wapen dat je zoekt.$B$BZoek de ijzeren kist in de kampen van de quilboars, en kom terug met de staven gesmeed staal.",
  o = "Breng de Forged Steel Bars naar Thun'grim Firegaze in de Barrens.",
  p = "Heb je mijn stalen staven?",
  c = "Je hebt ze gevonden! En alle staven zijn er. Dat verbaast me niet. Ik dacht al dat de Razormanes niet zouden weten wat ze met zulk mooi staal moesten doen.$b$bDank je, $N. Hier is je beloning. Ik hoop dat je er veel aan hebt.",
  g = { {"gesmeed", "forged (smeden)"}, {"staal", "steel"}, {"leidden me af", "distracted me (afleiden)"}, {"gesnuif", "snorting"}, {"stalen", "stole (stelen); also: steel (adj.)"}, {"lafaards", "cowards (lafaard)"}, {"ijzeren", "iron (adj.)"}, {"kist", "chest, box"}, {"staven", "bars (staaf)"}, {"terug kunt halen", "can get back, recover (terughalen)"}, {"verbaast", "surprises (verbazen)"}, {"beloning", "reward"} },
},

[1505] = { en = "Veteran Uzzek", tier = 1,
  t = "Veteraan Uzzek",
  d = "De Horde eert haar krijgers, want niemand twijfelt aan hun kracht. Maar de echt grote krijgers zijn ook goede leerlingen.$B$BZoek Uzzek op. Hij is een veteraan van veel gevechten, en nu leert hij jonge krijgers hoe ze moeten vechten. Je vindt hem ten zuiden van Far Watch Post. Dat is het garnizoen van de orcs op de grens van de Barrens en Durotar, in het oosten.",
  o = "Praat met Uzzek bij Far Watch Post.",
  c = "Hallo, jongeling. Ben je hier voor wat les?",
  g = { {"veteraan", "veteran"}, {"eert", "honours (eren)"}, {"twijfelt", "doubts (twijfelen)"}, {"leerlingen", "students (leerling)"}, {"Zoek ... op", "seek out (opzoeken)"}, {"gevechten", "battles (gevecht)"}, {"garnizoen", "garrison"}, {"grens", "border"}, {"jongeling", "young one, youngster"} },
},

[1818] = { en = "Speak with Dillinger", tier = 1,
  t = "Praat met Dillinger",
  d = "Ik hoorde dat Deathguard Dillinger een klus heeft voor iemand zoals jij. Wil je de troepen van de Dark Lady laten zien wat je waard bent? Meld je dan meteen bij Dillinger.$B$BDe post van Deathguard Dillinger is aan de westkant van Brill, bij het kerkhof.",
  o = "Praat met Deathguard Dillinger in Brill.",
  c = "Je bent hier voor een opdracht? Goed. Ik heb een belangrijke opdracht. Die test je vaardigheid in het gevecht... en je vastberadenheid in de verdediging van de Forsaken.",
  g = { {"klus", "job"}, {"troepen", "forces, troops (troep)"}, {"Meld je", "report (zich melden)"}, {"meteen", "immediately"}, {"kerkhof", "graveyard"}, {"opdracht", "mission, task"}, {"vastberadenheid", "resolve, determination"} },
},

[1819] = { en = "Ulag the Cleaver", tier = 1,
  t = "Ulag the Cleaver",
  d = "Toen de Scourge door Tirisfal Glades raasde, vingen we er een om hem te bestuderen. Hij had een vrije geest en noemde zichzelf Ulag the Cleaver. Zijn wil was vrij, maar hij stond nog steeds in de ban van de Lich King.$B$BWe hoopten een manier te vinden om de macht van de koning over Ulag te breken, maar dat lukte niet. Nu is het eindelijk tijd om hem te bevrijden.$B$BBevrijd hem, en dood hem.$B$BZet de schakelaar van de schedelsteen bij het mausoleum in het noorden aan. Die haalt het magische zegel weg dat hem vasthoudt.$B$BDan... wees klaar, $N.",
  o = "Dood Ulag the Cleaver en praat dan met Deathguard Dillinger.",
  p = "Je taak is nog niet af, $N. Het is niet slim voor een krijger om angst te tonen...",
  c = "Goed gedaan, $N. Ulag was geen kleine dienaar van de Scourge. Je hebt de Deathguards, en dus ook de Dark Lady, laten zien dat je een krijger bent met vaardigheid en vastberadenheid. Je bent het waard om meer te leren.",
  g = { {"raasde", "swept, raged (razen)"}, {"vingen", "captured, caught (vangen)"}, {"bestuderen", "to study"}, {"in de ban van", "in the thrall of, enthralled by"}, {"bevrijden", "to free"}, {"schakelaar", "trigger, switch"}, {"schedelsteen", "skull stone"}, {"zegel", "seal"}, {"vasthoudt", "binds, holds (vasthouden)"}, {"angst", "fear"}, {"tonen", "to show"}, {"dienaar", "servant, agent"}, {"vastberadenheid", "resolve"} },
},

[1820] = { en = "Speak with Coleman", tier = 1,
  t = "Praat met Coleman",
  d = "Je hebt de Dark Lady laten zien wat je waard bent. Nu kun je je misschien bewijzen aan een van haar onderdanen.$B$BColeman Farthing wacht op een krijger die zijn werktuig van wraak wil zijn tegen de vijanden van de Forsaken.$B$BJe vindt hem in de Gallow's End Tavern in het oosten van Brill.",
  o = "Praat met Coleman Farthing.",
  c = "Ja, het is waar. Ik heb je vechtkunst nodig. Ik heb weinig middelen, maar mijn taak helpt zowel mij als de zaak van de Forsaken. Doe het, en je krijgt een dubbele beloning.",
  g = { {"bewijzen", "to prove (zich bewijzen)"}, {"onderdanen", "subjects (onderdaan)"}, {"werktuig", "instrument, tool"}, {"wraak", "revenge"}, {"vijanden", "enemies (vijand)"}, {"vechtkunst", "combat skill"}, {"middelen", "means (middel)"}, {"zowel ... als", "both ... and"}, {"zaak", "cause"}, {"dubbele", "twofold, double (dubbel)"} },
