[1821] = { en = "Agamand Heirlooms", tier = 1,
  t = "Erfstukken van de Agamands",
  d = "De familie Agamand waren mijn werkgevers toen ik leefde, en zij waren de oorzaak van mijn dood! Het is terecht dat de Agamands nu hersenloze dienaren van de Lich King zijn.$B$BNu wil ik de laatste resten van hun eer. Ga naar hun familiecrypte en steel hun erfstukken: een zwaard, een bijl, een dolk en een strijdknots. Breng ze naar mij!$B$BDe familiecrypte van de Agamands ligt aan de noordkant van de molens van de Agamands. Loerende Scourge en dode Agamands bewaken hem.",
  o = "Breng de Agamand Family Axe, de Agamand Family Sword, de Agamand Family Mace en de Agamand Family dagger naar Coleman Farthing.",
  p = "Heb je de erfstukken, $N?",
  c = "Ah! Je hebt ze teruggehaald! Nu is de laatste schijn van eer en herinnering weggenomen uit de vervloekte landen van de Agamands. De familie bestaat echt niet meer!",
  g = { {"erfstukken", "heirlooms (erfstuk)"}, {"werkgevers", "employers (werkgever)"}, {"oorzaak", "cause"}, {"terecht", "fitting, justified"}, {"resten", "vestiges, remains (rest)"}, {"eer", "honour"}, {"familiecrypte", "family crypt"}, {"dolk", "dagger"}, {"strijdknots", "mace"}, {"molens", "mills (molen)"}, {"Loerende", "lurking (loeren)"}, {"bewaken", "guard (bewaken)"}, {"schijn", "semblance, appearance"}, {"vervloekte", "cursed (vervloekt)"} },
},

[1822] = { en = "Heirloom Weapon", tier = 1,
  t = "Het erfstukwapen",
  c = "Ik houd drie van de wapens die je me hebt teruggebracht, als herinnering aan mijn pijn en verlies. Maar alsjeblieft, $N, kies je favoriete erfstuk en houd het voor jezelf.$B$BIk hoop dat het jou beter dient dan zijn vervloekte vorige eigenaars.",
  g = { {"erfstukwapen", "heirloom weapon"}, {"teruggebracht", "returned, brought back (terugbrengen)"}, {"herinnering", "memento, memory"}, {"verlies", "loss"}, {"erfstuk", "heirloom"}, {"dient", "serves (dienen)"}, {"vervloekte", "cursed (vervloekt)"}, {"eigenaars", "owners (eigenaar)"} },
