[1823] = { en = "Speak with Ruga", tier = 1,
  t = "Praat met Ruga",
  d = "Je bent een krijger met vaardigheid en een groeiende naam. Ben je misschien klaar voor de beproeving van Ruga Ragetotem? Zo ja, zoek Ruga dan op in Camp Taurajo in de Barrens.$B$BHij wacht op de krijgers die zijn roep beantwoorden.",
