[1824] = { en = "Trial at the Field of Giants", tier = 1,
  t = "Beproeving bij het Field of Giants",
  d = "Om deze beproeving te halen, moet je naar het zuiden reizen, naar het Field of Giants. Daar vind je een grote groep kruipende insectenwezens. Ze zijn nieuw in de Barrens, en ik houd niet van wat hun komst aankondigt.$B$BBreng me hun voelsprieten die nog trillen, en verlies geen tijd, $N. Afgesneden voelsprieten trillen niet lang meer. Breng me de voelsprieten binnen de tijd, dan haal je de beproeving.",
  o = "Breng 5 Twitching Antennae naar Ruga Ragetotem in Camp Taurajo.",
  p = "Heb je de voelsprieten? Zo ja, geef ze dan snel aan mij, want trillende voelsprieten trillen niet voor altijd...",
  c = "Mooi gedaan, $N! Nu je de beproeving bij het Field of Giants hebt gehaald, zet je weer een stap verder op het pad van de $C.",
