[1825] = { en = "Speak with Thun'grim", tier = 1,
  t = "Praat met Thun'grim",
  d = "Thun'grim Firegaze, een beroemde orc-smid, heeft gehoord over je dappere daden in dienst van de Horde. Hij wil een harnas voor je maken, en hij vraagt je om meteen met hem te praten.$B$BThun'grim heeft zijn kamp ten oosten van de Crossroads in de Barrens.",
  o = "Praat met Thun'grim Firegaze in de Barrens.",
  c = "Ja, je bent gekomen. Dat is goed, want we hebben veel te bespreken, jij en ik.",
  g = { {"beroemde", "renowned, famous (beroemd)"}, {"smid", "blacksmith"}, {"dappere", "brave (dapper)"}, {"daden", "deeds (daad)"}, {"in dienst van", "in service of"}, {"harnas", "suit of armour"}, {"bespreken", "to discuss"} },
},

[1838] = { en = "Brutal Armor", tier = 2,
  t = "Brute wapenrusting",
  d = "Ik heb verhalen gehoord over je kracht en moed. Ik wil een wapenrusting voor je maken: een metgezel die je helpt, terwijl de verhalen over je grote daden groeien.$B$BMaar het maken van deze wapenrusting wordt een zoektocht op zich, $N. Ik heb jouw hulp nodig, en de hulp van andere smeden van de Horde.$B$BHier, neem deze rol. Ik heb vele nachten gezwoegd om op te schrijven wat ik nodig heb voor de wapenrusting, met mijn bijna blinde ogen. Breng me de dingen op deze rol, dan maak ik het eerste stuk van de wapenrusting voor je.",
  o = "Breng Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars en een Vial of Phlogiston.",
  p = "Heb je de dingen op mijn rol, $N?",
  c = "Je hebt alles gebracht wat ik vroeg. Nu zal ik mijn deel doen...",
  g = { {"Brute", "brutal (bruut)"}, {"wapenrusting", "suit of armour"}, {"moed", "valour, courage"}, {"metgezel", "companion"}, {"daden", "deeds (daad)"}, {"zoektocht op zich", "a quest in itself"}, {"smeden", "smiths (smid)"}, {"rol", "scroll"}, {"gezwoegd", "toiled, struggled (zwoegen)"}, {"blinde", "blind (blind)"}, {"deel", "part, share"} },
},

