  t = "Ula'elek en de Brutal Gauntlets",
  d = "De trollensmid Ula'elek zal de Brutal Gauntlets voor je maken. Hij woont in Durotar, in Sen'jin Village, bij zijn broeders van de Darkspear, en hij wacht op je komst.",
  o = "Praat met Ula'elek in Durotar.",
