[1841] = { en = "Velora Nitely and the Brutal Legguards", tier = 2,
  t = "Velora Nitely en de Brutal Legguards",
  d = "Men zegt dat Velora Nitely voor haar dood een van de beste harnassmeden van Lordaeron was. De dood heeft haar talent blijkbaar niet kleiner gemaakt. Praat met Velora. Zij maakt je Brutal Legguards.$B$BVelora oefent haar vak uit in de Undercity van Lordaeron, in de handelswijk.",
  o = "Praat met Velora Nitely in de Undercity.",
  c = "Je bent hier voor beenbescherming? Geweldig!$b$bEh... maak ik het harnas voor jou, of maak jij het voor mij?$b$bDat was een grap. Was het grappig? Ik weet het niet... Ik verloor mijn gevoel voor humor op hetzelfde moment als mijn reukzin. Dat gebeurde ongeveer toen ik stopte met ademen.",
  g = { {"Men zegt", "it is said"}, {"harnassmeden", "armoursmiths (harnassmid)"}, {"blijkbaar", "it seems, apparently"}, {"oefent haar vak uit", "plies her trade (uitoefenen)"}, {"handelswijk", "trade quarter"}, {"beenbescherming", "leg armour"}, {"grap", "joke"}, {"gevoel voor humor", "sense of humour"}, {"reukzin", "sense of smell"}, {"ademen", "breathing (ademen)"} },
},

[1842] = { en = "Satyr Hooves", tier = 2,
  t = "Saterhoeven",
  d = "Ik kan een paar Brutal Gauntlets voor je maken, en er zal grote magie in zitten. Maar eerst moet je die magie verzamelen en naar mij brengen.$B$BDe saters wonen in het noordoosten van Ashenvale, vanwege de kracht van het bos. Ze voeden zich met de zuiverheid ervan. Ze zuigen het leeg en bederven het. Aan hun opgezwollen, ongespleten hoeven kun je zien welke saters de meeste magie van Ashenvale hebben opgenomen.$B$BDie hoeven hebben grote kracht. Ik heb ze nodig om je handschoenen te maken.",
  o = "Breng 7 Uncloven Satyr Hooves naar Ula'elek in Sen'jin Village in Durotar.",
  p = "Heb je de hoeven, $N? De magie erin is sterk.",
  c = "Ah, je hebt ze! De saters zogen de kracht van Ashenvale leeg. Zo zal ik nu de kracht uit deze hoeven zuigen, en die gebruiken bij mijn smeedwerk...",
