[1844] = { en = "Chimaeric Horn", tier = 2,
  t = "De hoorn van de chimaera",
  d = "Ik zal de helm voor je maken, maar je moet me laten zien dat je hem waard bent.$B$BVer in het noordwesten van de Stonetalon Mountains ligt de Charred Vale. Ooit was het een groene plek, maar nu is het bezoedeld en vol as. De wezens die er nog leven, zijn gek van pijn en wanhoop.$B$BDaar stuur ik je heen, $N.$B$BJe moet naar de Charred Vale gaan en een Chimaera Matriarch vinden. Dood haar en verlos haar van haar ellende. Breng me haar gegalvaniseerde hoorn als bewijs, dan maak ik de helm voor je.",
  o = "Breng een Galvanized Horn naar Orm Stonehoof in Thunder Bluff.",
  p = "Heb je de hoorn? Is de matriarch verlost van haar pijn?",
  c = "Je hebt je taak volbracht, $N. Je hebt me je waarde en vastberadenheid laten zien. De helm wordt van jou...",
  g = { {"chimaera", "chimaera"}, {"hoorn", "horn"}, {"waard", "worthy, worth"}, {"Ooit", "once"}, {"bezoedeld", "defiled"}, {"as", "ash"}, {"wanhoop", "despair"}, {"verlos", "free, release (verlossen)"}, {"ellende", "misery"}, {"gegalvaniseerde", "galvanized"}, {"matriarch", "matriarch"}, {"volbracht", "completed, accomplished (volbrengen)"}, {"vastberadenheid", "resolve"} },
},

