[1846] = { en = "Dragonmaw Shinbones", tier = 2,
  t = "Scheenbenen van de Dragonmaw",
  d = "Om de Brutal Legguards te maken, heb ik een stel stevige scheenbenen nodig. De orcs van de Dragonmaw in de Wetlands hebben mooie, dikke scheenbenen. Die van hen heb ik nodig.$B$BMaar ze moeten stevig zijn. Test de scheenbenen goed terwijl je ze verzamelt. Als je ze met je blote handen kunt breken, zijn ze niet stevig genoeg om mee te werken.",
  o = "Breng 8 Sturdy Dragonmaw Shinbones naar Velora Nitely in de Undercity.",
  p = "Ik wacht op die scheenbenen, $N. Ze worden een mooi frame voor je beenbeschermers.",
  c = "Goed gedaan! Deze zien er allemaal sterk uit. Ik denk dat ze heel goed zullen werken. Hoe vonden die orcs het dat je hun schenen meenam, $N? Klaagden ze veel?$B$BDat was weer een grap. Je lacht niet.$B$BIk ben tegenwoordig niet erg grappig, hè...",
  g = { {"Scheenbenen", "shinbones (scheenbeen)"}, {"een stel", "a brace, a set"}, {"stevige", "sturdy (stevig)"}, {"blote", "bare (bloot)"}, {"frame", "frame"}, {"beenbeschermers", "leg guards (beenbeschermer)"}, {"schenen", "shins (scheen)"}, {"meenam", "took along (meenemen)"}, {"Klaagden", "complained (klagen)"}, {"grap", "joke"}, {"tegenwoordig", "these days"} },
},

